import java.io.*;
class ThermostatData implements Serializable {private static final long serialVersionUID=1L;String location;int temperature;transient String temporaryNote;ThermostatData(String l,int t,String n){location=l;temperature=t;temporaryNote=n;}}
public class Main {public static void main(String[] args)throws Exception{ThermostatData[] data={new ThermostatData("Lab",24,"not saved"),new ThermostatData("Library",22,"temporary")};try(ObjectOutputStream out=new ObjectOutputStream(new FileOutputStream("objects.dat"))){out.writeObject(data);}try(ObjectInputStream in=new ObjectInputStream(new FileInputStream("objects.dat"))){ThermostatData[] loaded=(ThermostatData[])in.readObject();for(ThermostatData d:loaded)System.out.println(d.location+" "+d.temperature+" temporaryNote="+d.temporaryNote);}}}
